import os, tempfile

APP_UID, APP_GIDS = 1000, [1000]

def access_for(st, need):
    mode = st.st_mode & 0o777
    if st.st_uid == APP_UID:
        bits = (mode >> 6) & 0o7
    elif st.st_gid in APP_GIDS:
        bits = (mode >> 3) & 0o7
    else:
        bits = mode & 0o7
    return (bits & need) == need

