import importlib, importlib.resources, os, sys, tempfile

def make_pkg(base, name, with_data):
    pkg = os.path.join(base, name)
    os.makedirs(pkg)
    open(os.path.join(pkg, "__init__.py"), "w").close()
    if with_data:
        with open(os.path.join(pkg, "rates.txt"), "w") as f:
            f.write("rates v1")
